thread-resume-race.code:
[ORCHESTRATION_WS_METHODS.subscribeThread]: (input) =>
  observeRpcStreamEffect(
    ORCHESTRATION_WS_METHODS.subscribeThread,
    Effect.gen(function* () {
      const isThisThreadDetailEvent = (event: OrchestrationEvent) =>
        event.aggregateKind === "thread" &&
        event.aggregateId === input.threadId &&
        isThreadDetailEvent(event);

      const liveStream = orchestrationEngine.streamDomainEvents.pipe(
        Stream.filter(isThisThreadDetailEvent),
        Stream.map((event) => ({
          kind: "event" as const,
          event: projectActivityEvent(event),
        })),
      );

      // Attach live delivery before reading either replay or snapshot state.
      // Otherwise an event published while the snapshot is loading is lost.
      const liveBuffer = yield* Queue.unbounded<OrchestrationThreadStreamItem>();
      yield* Effect.forkScoped(
        liveStream.pipe(Stream.runForEach((item) => Queue.offer(liveBuffer, item))),
      );
      const bufferedLiveStream = Stream.fromQueue(liveBuffer);

      // When the client already loaded the snapshot over HTTP it passes
      // that snapshot's sequence, and we resume the live subscription by
      // replaying persisted events after it instead of re-sending the
      // (potentially multi-KB) snapshot frame over the socket.
      //
      // The live PubSub subscription must be attached *before* draining
      // the catch-up replay, otherwise events published during the replay
      // window are dropped (they are past the persisted tail the replay
      // read, but the live stream is not yet subscribed). So fork the
      // live stream into a buffer bound to this stream's scope, then emit
      // catch-up followed by the buffered/ongoing live events. Overlapping
      // events are deduped by sequence on the client.
      //
      // The replay is bounded to the projection head captured below. The
      // catch-up range is normally tiny (a fresh HTTP snapshot sequence),
      // but a stale cached cursor can sit hundreds of thousands of global
      // events behind — replaying that decodes every intervening event
      // (including every other thread's tool payloads) only to discard
      // almost all of them, which has OOM-killed servers on large
      // databases. A truncated replay would silently drop this thread's
      // events, so past the gap cap we reset the client with a fresh
      // thread snapshot instead, exactly like subscribeShell above.
      if (input.afterSequence !== undefined) {
        const afterSequence = input.afterSequence;
        const headSequence = yield* orchestrationEngine.latestSequence;
        const replayGap = headSequence - afterSequence;
        if (replayGap >= 0 && replayGap <= THREAD_RESUME_MAX_GAP) {
          const catchUpStream = orchestrationEngine
            .readEvents(afterSequence, replayGap)
            .pipe(
              Stream.filter(isThisThreadDetailEvent),
              Stream.map((event) => ({
                kind: "event" as const,
                event: projectActivityEvent(event),
              })),
              Stream.mapError(
                (cause) =>
                  new OrchestrationGetSnapshotError({
                    message: `Failed to replay thread ${input.threadId} events`,
                    cause,
                  }),
              ),
            );
          const afterCatchUp =
            input.requestCompletionMarker === true
              ? Stream.concat(
                  Stream.fromEffect(
                    Queue.offer(liveBuffer, { kind: "synchronized" as const }),
                  ).pipe(Stream.drain),
                  bufferedLiveStream,
                )
              : bufferedLiveStream;
          return Stream.concat(catchUpStream, afterCatchUp);
        }
        // Gap too large (or cursor ahead of authoritative state): fall
        // through to the snapshot path so the client converges from a
        // fresh thread detail instead of an unbounded replay.
      }

      const snapshot = yield* projectionSnapshotQuery
        .getThreadDetailSnapshot(
          input.threadId,
          // Windowing the fallback snapshot is opt-in per subscription:
          // clients that don't send turnLimit (including all
          // pre-pagination clients) get the full thread, since they
          // have no way to load older pages.
          input.turnLimit === undefined ? undefined : { turnLimit: input.turnLimit },
        )
        .pipe(
          Effect.mapError(
            (cause) =>
              new OrchestrationGetSnapshotError({
                message: `Failed to load thread ${input.threadId}`,
                cause,
              }),
          ),
        );

      if (Option.isNone(snapshot)) {
        return yield* new OrchestrationGetSnapshotError({
          message: `Thread ${input.threadId} was not found`,
          cause: input.threadId,
        });
      }

      const afterSnapshot =
        input.requestCompletionMarker === true
          ? Stream.concat(
              Stream.fromEffect(
                Queue.offer(liveBuffer, { kind: "synchronized" as const }),
              ).pipe(Stream.drain),
              bufferedLiveStream,
            )
          : bufferedLiveStream;
      return Stream.concat(
        Stream.make({
          kind: "snapshot" as const,
          snapshot: projectThreadDetailSnapshot(snapshot.value),
        }),
        afterSnapshot,
      );
    }),
    { "rpc.aggregate": "orchestration" },

auth-credential-precedence.code:
const authenticateRequest = (
  request: HttpServerRequest.HttpServerRequest,
): Effect.Effect<AuthenticatedSession, ServerAuthCredentialError | ServerAuthInternalError> => {
  const cookieToken = request.cookies[sessions.cookieName];
  const bearerToken = parseBearerToken(request);
  const dpopToken = parseDpopToken(request);
  const credential = cookieToken ?? bearerToken ?? dpopToken;
  if (!credential) {
    return Effect.fail(new ServerAuthMissingCredentialError({}));
  }
  return authenticateToken(credential).pipe(
    Effect.flatMap((session) => {
      if (session.proofKeyThumbprint) {
        if (!dpopToken || dpopToken !== credential) {
          return Effect.fail(
            new ServerAuthInvalidCredentialError({
              diagnostic: "DPoP-bound access token requires DPoP authorization.",
            }),
          );
        }
        return verifyRequestDpopProof({
          request,
          expectedThumbprint: session.proofKeyThumbprint,
          expectedAccessToken: dpopToken,
        }).pipe(
          Effect.provideService(ServerSecretStore.ServerSecretStore, secretStore),
          Effect.provideService(Crypto.Crypto, crypto),
          Effect.as(session),
        );
      }
      if (dpopToken) {
        return Effect.fail(
          new ServerAuthInvalidCredentialError({
            diagnostic: "DPoP authorization requires a proof-bound access token.",
          }),
        );
      }
      return Effect.succeed(session);
    }),
  );
};

websocket-ticket-verification.code:
const verifyWebSocketToken: SessionStore["Service"]["verifyWebSocketToken"] = Effect.fn(
  "SessionStore.verifyWebSocketToken",
)(function* (token) {
  const [encodedPayload, signature] = token.split(".");
  if (!encodedPayload || !signature) {
    return yield* new MalformedWebSocketTokenError({});
  }

  const expectedSignature = signPayload(encodedPayload, signingSecret);
  if (!timingSafeEqualBase64Url(signature, expectedSignature)) {
    return yield* new InvalidWebSocketTokenSignatureError({});
  }

  const claims = yield* decodeWebSocketClaims(base64UrlDecodeUtf8(encodedPayload)).pipe(
    Effect.mapError((cause) => new InvalidWebSocketTokenPayloadError({ cause })),
  );

  const observedAt = yield* DateTime.now;
  const expiresAt = DateTime.make(claims.exp);
  if (Option.isNone(expiresAt)) {
    return yield* new InvalidSessionExpirationClaimError({
      sessionId: claims.sid,
      expirationClaim: claims.exp,
    });
  }
  if (claims.exp <= observedAt.epochMilliseconds) {
    return yield* new WebSocketTokenExpiredError({
      sessionId: claims.sid,
      expiresAt: expiresAt.value,
      observedAt,
    });
  }

  const row = yield* authSessions
    .getById({ sessionId: claims.sid })
    .pipe(
      Effect.mapError(
        (cause) => new WebSocketTokenVerificationError({ sessionId: claims.sid, cause }),
      ),
    );
  if (Option.isNone(row)) {
    return yield* new UnknownWebSocketSessionError({ sessionId: claims.sid });
  }
  if (row.value.expiresAt.epochMilliseconds <= observedAt.epochMilliseconds) {
    return yield* new WebSocketSessionExpiredError({
      sessionId: claims.sid,
      expiresAt: row.value.expiresAt,
      observedAt,
    });
  }
  if (row.value.revokedAt !== null) {
    return yield* new WebSocketSessionRevokedError({
      sessionId: claims.sid,
      revokedAt: row.value.revokedAt,
    });
  }

  return {
    sessionId: row.value.sessionId,
    token,
    method: row.value.method,
    client: toClientMetadata(row.value.client),
    expiresAt: row.value.expiresAt,
    subject: row.value.subject,
    scopes: row.value.scopes,
  } satisfies VerifiedSession;
});

normalizer-staging-boundary.code:
export const canonicalizeClientCommandTimestamps = (
  command: ClientOrchestrationCommand,
  receivedAt: IsoDateTime,
): ClientOrchestrationCommand => {
  const canonicalCommand =
    "createdAt" in command
      ? {
          ...command,
          createdAt: receivedAt,
        }
      : command;

  if (canonicalCommand.type !== "thread.turn.start" || !canonicalCommand.bootstrap?.createThread) {
    return canonicalCommand;
  }

  return {
    ...canonicalCommand,
    bootstrap: {
      ...canonicalCommand.bootstrap,
      createThread: {
        ...canonicalCommand.bootstrap.createThread,
        createdAt: receivedAt,
      },
    },
  };
};

export const normalizeDispatchCommand = (command: ClientOrchestrationCommand) =>
  Effect.gen(function* () {
    const receivedAt = DateTime.formatIso(yield* DateTime.now);
    const canonicalCommand = canonicalizeClientCommandTimestamps(command, receivedAt);
    const fileSystem = yield* FileSystem.FileSystem;
    const path = yield* Path.Path;
    const serverConfig = yield* ServerConfig;
    const workspacePaths = yield* WorkspacePaths.WorkspacePaths;

    const normalizeProjectWorkspaceRoot = (workspaceRoot: string) =>
      workspacePaths.normalizeWorkspaceRoot(workspaceRoot).pipe(
        Effect.mapError(
          (cause) =>
            new OrchestrationDispatchCommandError({
              message: cause.message,
            }),
        ),
      );

    const normalizeProjectWorkspaceRootForCreate = (
      workspaceRoot: string,
      createIfMissing: boolean | undefined,
    ) =>
      workspacePaths
        .normalizeWorkspaceRoot(workspaceRoot, {
          createIfMissing: createIfMissing === true,
        })
        .pipe(
          Effect.mapError(
            (cause) =>
              new OrchestrationDispatchCommandError({
                message: cause.message,
              }),
          ),
        );

    if (canonicalCommand.type === "project.create") {
      return {
        ...canonicalCommand,
        workspaceRoot: yield* normalizeProjectWorkspaceRootForCreate(
          canonicalCommand.workspaceRoot,
          canonicalCommand.createWorkspaceRootIfMissing,
        ),
        createWorkspaceRootIfMissing: canonicalCommand.createWorkspaceRootIfMissing === true,
      } satisfies OrchestrationCommand;
    }

    if (
      canonicalCommand.type === "project.meta.update" &&
      canonicalCommand.workspaceRoot !== undefined
    ) {
      return {
        ...canonicalCommand,
        workspaceRoot: yield* normalizeProjectWorkspaceRoot(canonicalCommand.workspaceRoot),
      } satisfies OrchestrationCommand;
    }

    if (canonicalCommand.type !== "thread.turn.start") {
      return canonicalCommand as OrchestrationCommand;
    }

    const normalizedAttachments = yield* Effect.forEach(
      canonicalCommand.message.attachments,
      (attachment) =>
        Effect.gen(function* () {
          const parsed = parseBase64DataUrl(attachment.dataUrl);
          if (!parsed || !parsed.mimeType.startsWith("image/")) {
            return yield* new OrchestrationDispatchCommandError({
              message: `Invalid image attachment payload for '${attachment.name}'.`,
            });
          }

          const bytes = Buffer.from(parsed.base64, "base64");
          if (bytes.byteLength === 0 || bytes.byteLength > PROVIDER_SEND_TURN_MAX_IMAGE_BYTES) {
            return yield* new OrchestrationDispatchCommandError({
              message: `Image attachment '${attachment.name}' is empty or too large.`,
            });
          }

          const attachmentId = createAttachmentId(canonicalCommand.threadId);
          if (!attachmentId) {
            return yield* new OrchestrationDispatchCommandError({
              message: "Failed to create a safe attachment id.",
            });
          }

          const persistedAttachment = {
            type: "image" as const,
            id: attachmentId,
            name: attachment.name,
            mimeType: parsed.mimeType.toLowerCase(),
            sizeBytes: bytes.byteLength,
          };

          const attachmentPath = resolveAttachmentPath({
            attachmentsDir: serverConfig.attachmentsDir,
            attachment: persistedAttachment,
          });
          if (!attachmentPath) {
            return yield* new OrchestrationDispatchCommandError({
              message: `Failed to resolve persisted path for '${attachment.name}'.`,
            });
          }

          yield* fileSystem.makeDirectory(path.dirname(attachmentPath), { recursive: true }).pipe(
            Effect.mapError(
              () =>
                new OrchestrationDispatchCommandError({
                  message: `Failed to create attachment directory for '${attachment.name}'.`,
                }),
            ),
          );
          yield* fileSystem.writeFile(attachmentPath, bytes).pipe(
            Effect.mapError(
              () =>
                new OrchestrationDispatchCommandError({
                  message: `Failed to persist attachment '${attachment.name}'.`,
                }),
            ),
          );

          return persistedAttachment;
        }),
      { concurrency: 1 },
    );

    return {
      ...canonicalCommand,
      message: {
        ...canonicalCommand.message,
        attachments: normalizedAttachments,
      },
    } satisfies OrchestrationCommand;
  });

